import{_ as a,o as i,c as t,a3 as n}from"./chunks/framework.Dz5Q8p4s.js";const u=JSON.parse('{"title":"Post-Training & Reinforcement Learning in Video Generation","description":"","frontmatter":{"title":"Post-Training & Reinforcement Learning in Video Generation","outline":[2,2]},"headers":[],"relativePath":"en/tutorials/post-training-rl.md","filePath":"en/tutorials/post-training-rl.md","lastUpdated":null}'),r={name:"en/tutorials/post-training-rl.md"};function o(l,e,s,d,h,p){return i(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="post-training-reinforcement-learning-in-video-generation" tabindex="-1">Post-Training &amp; Reinforcement Learning in Video Generation <a class="header-anchor" href="#post-training-reinforcement-learning-in-video-generation" aria-label="Permalink to &quot;Post-Training &amp; Reinforcement Learning in Video Generation&quot;">​</a></h1><blockquote><p><strong>Full text (Chinese)</strong>: <a href="/notes/tutorials/post-training-rl">视频生成中的后训练与强化学习</a><strong>Coverage</strong>: June 2025 onward, with the foundational 2023 – mid-2025 work read paper by paper. <strong>Papers</strong>: <a href="/notes/en/papers/#tut-post-training-rl">61 deep-read notes</a></p></blockquote><div class="warning custom-block"><p class="custom-block-title">About this English page</p><p>The tutorial itself is written in Chinese. This page is its English companion: it gives the complete chapter-by-chapter structure and states what each chapter argues. Every derivation, table, diagram and per-paper breakdown lives in the <a href="/notes/tutorials/post-training-rl">Chinese edition</a>; the <a href="/notes/en/papers/">paper library</a> is fully browsable in English.</p></div><h2 id="what-this-tutorial-is-about" tabindex="-1">What this tutorial is about <a class="header-anchor" href="#what-this-tutorial-is-about" aria-label="Permalink to &quot;What this tutorial is about&quot;">​</a></h2><p>The framing analogy is explicit: pretraining → post-training in video generation plays the same role as GPT → ChatGPT in language. Pretraining buys competence; post-training buys usefulness and alignment, and there is a specific class of problems — aesthetic preference, motion quality, instruction compliance, physical plausibility — that more pretraining data does not fix.</p><p>The technical key is Chapter 2&#39;s reframing: <strong>one denoising or integration trajectory is a decision trajectory, so sampling is an MDP</strong>. Once that is accepted, three families follow — reward backpropagation, direct preference optimisation (the DPO family), and policy gradients with GRPO — and the tutorial gives a decision tree for choosing among them plus the three adversaries that stalk all three: reward hacking, distribution collapse, and the cost of video rollouts.</p><h2 id="chapter-outline" tabindex="-1">Chapter outline <a class="header-anchor" href="#chapter-outline" aria-label="Permalink to &quot;Chapter outline&quot;">​</a></h2><h3 id="chapter-0-—-why-video-generation-needs-post-training-and-rl" tabindex="-1">Chapter 0 — Why video generation needs post-training and RL <a class="header-anchor" href="#chapter-0-—-why-video-generation-needs-post-training-and-rl" aria-label="Permalink to &quot;Chapter 0 — Why video generation needs post-training and RL&quot;">​</a></h3><ul><li>0.1 The one-sentence version</li><li>0.2 The analogy: pretraining → post-training is video generation&#39;s GPT → ChatGPT</li><li>0.3 What post-training fixes that pretraining cannot</li><li>0.4 Suggested reading route</li></ul><h3 id="chapter-1-—-foundations-video-generators-and-the-post-training-landscape" tabindex="-1">Chapter 1 — Foundations: video generators and the post-training landscape <a class="header-anchor" href="#chapter-1-—-foundations-video-generators-and-the-post-training-landscape" aria-label="Permalink to &quot;Chapter 1 — Foundations: video generators and the post-training landscape&quot;">​</a></h3><ul><li>1.1 Three mainstream generation paradigms</li><li>1.2 Representative open and commercial base models</li><li>1.3 What &quot;post-training&quot; actually comprises</li><li>1.4 Terminology quick-reference</li></ul><h3 id="chapter-2-—-principles-turning-sampling-into-a-learnable-decision-process" tabindex="-1">Chapter 2 — Principles: turning sampling into a learnable decision process <a class="header-anchor" href="#chapter-2-—-principles-turning-sampling-into-a-learnable-decision-process" aria-label="Permalink to &quot;Chapter 2 — Principles: turning sampling into a learnable decision process&quot;">​</a></h3><ul><li>2.1 The key view: one denoising/integration pass = one decision trajectory (an MDP)</li><li>2.2 Why a supervised loss cannot simply &quot;raise quality&quot;</li><li>2.3 An overview of the three families</li><li>2.4 Family 1: reward backpropagation</li><li>2.5 Family 2: direct preference optimisation (the DPO family)</li><li>2.6 Family 3: policy gradients and GRPO — the protagonist of 2025</li><li>2.7 A unified view and a decision tree</li><li>2.8 The three adversaries that run through everything</li></ul><h3 id="chapter-3-—-tasks-which-video-capabilities-post-training-actually-optimises" tabindex="-1">Chapter 3 — Tasks: which video capabilities post-training actually optimises <a class="header-anchor" href="#chapter-3-—-tasks-which-video-capabilities-post-training-actually-optimises" aria-label="Permalink to &quot;Chapter 3 — Tasks: which video capabilities post-training actually optimises&quot;">​</a></h3><ul><li>3.1 Panorama of tasks</li><li>3.2 Task-by-task walkthrough, including which reward to use</li><li>3.3 A unified mental model for multi-objective rewards</li></ul><h3 id="chapter-4-—-evaluation-and-reward-benchmarks-and-reward-models" tabindex="-1">Chapter 4 — Evaluation and reward: benchmarks and reward models <a class="header-anchor" href="#chapter-4-—-evaluation-and-reward-benchmarks-and-reward-models" aria-label="Permalink to &quot;Chapter 4 — Evaluation and reward: benchmarks and reward models&quot;">​</a></h3><ul><li>4.1 Video-generation benchmarks</li><li>4.2 Reward models — the scorer that RL depends on</li><li>4.3 How to choose and combine rewards: an engineering checklist</li></ul><h3 id="chapter-5-—-data-building-preference-data-and-prompt-data" tabindex="-1">Chapter 5 — Data: building preference data and prompt data <a class="header-anchor" href="#chapter-5-—-data-building-preference-data-and-prompt-data" aria-label="Permalink to &quot;Chapter 5 — Data: building preference data and prompt data&quot;">​</a></h3><ul><li>5.1 What data is required</li><li>5.2 Prompt data</li><li>5.3 Preference data</li><li>5.4 Three labelling approaches compared</li><li>5.5 Synthetic and self-improvement data</li><li>5.6 Empirical intuition about data scale</li></ul><h3 id="chapter-6-—-methods-five-families-in-detail" tabindex="-1">Chapter 6 — Methods: five families in detail <a class="header-anchor" href="#chapter-6-—-methods-five-families-in-detail" aria-label="Permalink to &quot;Chapter 6 — Methods: five families in detail&quot;">​</a></h3><ul><li>6.1 Reward backpropagation / direct reward fine-tuning</li><li>6.2 Preference optimisation (the DPO family)</li><li>6.3 Policy gradients / GRPO (online RL)</li><li>6.4 Adversarial post-training plus distillation combined with RL, for few-step high quality</li><li>6.5 Inference-time and prompt-level alignment (training-free)</li><li>6.6 A full comparison of the five families</li></ul><h3 id="chapter-7-—-paper-map-key-work-from-2025-06-onward-read-one-by-one" tabindex="-1">Chapter 7 — Paper map: key work from 2025-06 onward, read one by one <a class="header-anchor" href="#chapter-7-—-paper-map-key-work-from-2025-06-onward-read-one-by-one" aria-label="Permalink to &quot;Chapter 7 — Paper map: key work from 2025-06 onward, read one by one&quot;">​</a></h3><ul><li>7.1 Foundational must-reads, dissected individually (2023 – mid-2025)</li><li>7.2 GRPO and policy-gradient work</li><li>7.3 Preference optimisation / DPO, including video-specific variants</li><li>7.4 Identity, subject and multi-subject consistency via RL or preference signals</li><li>7.5 Motion, temporal behaviour, physics and world models</li><li>7.6 Few-step distillation combined with RL</li><li>7.7 Inference-time, prompt-level and agentic alignment</li><li>7.8 Reward models and evaluation — the compass for alignment</li><li>7.9 Timeline overview</li></ul><h3 id="chapter-8-—-practice-running-a-video-rl-post-training-job" tabindex="-1">Chapter 8 — Practice: running a video RL post-training job <a class="header-anchor" href="#chapter-8-—-practice-running-a-video-rl-post-training-job" aria-label="Permalink to &quot;Chapter 8 — Practice: running a video RL post-training job&quot;">​</a></h3><ul><li>8.1 The end-to-end pipeline</li><li>8.2 Key decisions and recommendations</li><li>8.3 A memory and cost checklist</li><li>8.4 Common pitfalls and how to diagnose them</li><li>8.5 Open-source frameworks you can start from</li><li>8.6 A minimum viable setup</li></ul><h3 id="chapter-9-—-challenges-traps-and-future-directions" tabindex="-1">Chapter 9 — Challenges, traps and future directions <a class="header-anchor" href="#chapter-9-—-challenges-traps-and-future-directions" aria-label="Permalink to &quot;Chapter 9 — Challenges, traps and future directions&quot;">​</a></h3><ul><li>9.1 Unsolved core challenges</li><li>9.2 Trend calls (2025 → 2026)</li><li>9.3 Advice for different roles</li></ul><h3 id="chapter-10-—-resources" tabindex="-1">Chapter 10 — Resources <a class="header-anchor" href="#chapter-10-—-resources" aria-label="Permalink to &quot;Chapter 10 — Resources&quot;">​</a></h3><ul><li>10.1 Continuously updated paper lists</li><li>10.2 Key open-source code</li><li>10.3 Base models</li><li>10.4 Chinese–English terminology reference</li></ul><h2 id="related-tutorials" tabindex="-1">Related tutorials <a class="header-anchor" href="#related-tutorials" aria-label="Permalink to &quot;Related tutorials&quot;">​</a></h2><ul><li><a href="/notes/en/tutorials/acceleration-distillation">Acceleration &amp; Distillation</a> — the joint few-step-plus-quality problem from the other side</li><li><a href="/notes/en/tutorials/physics-aware">Physics-Aware Video Generation</a> — physical plausibility as a reward</li><li><a href="/notes/en/tutorials/agentic">Agentic Video Generation</a> — agentic RL for orchestration policies</li></ul>',31)])])}const m=a(r,[["render",o]]);export{u as __pageData,m as default};
